package com.muxigame.city;
import java.util.*;
import net.minecraft.core.BlockPos;
import net.minecraft.gametest.framework.*;
import net.minecraft.nbt.CompoundTag;
import net.minecraft.world.level.block.Blocks;
import net.neoforged.neoforge.gametest.*;
@GameTestHolder(CityMod.ID) @PrefixGameTestTemplate(false)
public class CityTestsHousing {
 @GameTest(template="empty") public static void largeHouseRegistryWritesRealNbt(GameTestHelper helper){try{var data=new CityData();var c=city();c.bounds=CityBounds.between(BlockPos.ZERO,new BlockPos(63,15,63));UUID id=UUID.randomUUID();c.buildings.put(id,new CityRegistry.Building(id,"大房屋","住宅",c.bounds));var h=CityHousing.house(c,id);for(int i=0;i<8192;i++)h.baseline.put(c.bounds.at(i).asLong(),CityMaintenance.encode((i%2==0?Blocks.OAK_PLANKS:Blocks.GLASS).defaultBlockState()));data.cities.put(c.id,c);var saved=data.save(new CompoundTag(),helper.getLevel().registryAccess());var bytes=new java.io.ByteArrayOutputStream();net.minecraft.nbt.NbtIo.write(saved,new java.io.DataOutputStream(bytes));helper.assertTrue(bytes.size()>65535,"Exercise registry beyond short UTF string capacity");var loaded=CityData.load(saved,helper.getLevel().registryAccess());helper.assertTrue(loaded.require(c.id).housing.houses.get(id).baseline.size()==8192,"Large baseline survives persistence");var legacy=new CityData();var small=city();legacy.cities.put(small.id,small);var old=legacy.save(new CompoundTag(),helper.getLevel().registryAccess());old.putInt("Schema",2);var row=old.getList("Cities",10).getCompound(0);row.putString("Registry",new String(row.getByteArray("RegistryUtf8"),java.nio.charset.StandardCharsets.UTF_8));row.remove("RegistryUtf8");helper.assertTrue(CityData.load(old,helper.getLevel().registryAccess()).cities.size()==1,"Actual old string registry remains readable");helper.succeed();}catch(Exception ex){helper.fail(ex.toString());}}
 @GameTest(template="empty",timeoutTicks=100) public static void captureAndDamageUseRealWorldBlocks(GameTestHelper helper){var server=helper.getLevel().getServer();var data=CityData.get(server);var origin=helper.absolutePos(new BlockPos(0,1,0));var bounds=CityBounds.between(origin,origin.offset(2,2,2));var c=data.create(UUID.randomUUID(),"房屋血量实测",helper.getLevel().dimension().location().toString(),bounds);UUID id=UUID.randomUUID();c.buildings.put(id,new CityRegistry.Building(id,"小屋","住宅",bounds));var h=CityHousing.house(c,id);h.configured=true;h.personal=false;var pos=origin.offset(1,1,1);helper.getLevel().setBlock(pos,Blocks.GLASS.defaultBlockState(),3);CityHousing.capture(server,c,id);helper.runAfterDelay(8,()->{helper.assertTrue(h.baseline.containsKey(pos.asLong()),"Capture records real building block");helper.getLevel().setBlock(pos,Blocks.AIR.defaultBlockState(),3);CityHousing.changed(helper.getLevel(),pos,true);helper.assertTrue(h.damaged.contains(pos.asLong()),"Breaking block immediately lowers data health");var economy=CityEconomy.get(server);economy.state.accounts.put(CityEconomy.treasury(c.id),10L);var stock=new CityHousing.Material();stock.priceCents=100;stock.stock=2;c.housing.market.put("minecraft:glass",stock);helper.assertTrue(CityHousing.repairMaterial(server,c,pos,Blocks.GLASS.defaultBlockState())&&stock.stock==1&&economy.balance(CityEconomy.treasury(c.id))==9,"Repair buys and consumes its actual material from public funds");CityHousing.repaired(server,c,pos);helper.assertTrue(!h.damaged.contains(pos.asLong()),"Data repair restores health before world projection");helper.getLevel().setBlock(pos,Blocks.GLASS.defaultBlockState(),3);CityHousing.changed(helper.getLevel(),pos,false);economy.state.accounts.remove(CityEconomy.treasury(c.id));economy.state.accounts.remove("market:"+c.id);helper.assertTrue(!h.damaged.contains(pos.asLong()),"Restoring target immediately restores health");data.cities.remove(c.id);CityMaintenance.get(server).state.cities.remove(c.id);helper.succeed();});}
 static CityData.City city(){return new CityData.City(UUID.randomUUID(),UUID.randomUUID(),"房屋规则验证","minecraft:overworld",CityBounds.between(BlockPos.ZERO,new BlockPos(15,15,15)));}
 static UUID building(CityData.City c,int offset){UUID id=UUID.randomUUID();c.buildings.put(id,new CityRegistry.Building(id,"住宅"+offset,"住宅",CityBounds.between(new BlockPos(offset,0,0),new BlockPos(offset+2,2,2))));return id;}
 @GameTest(template="empty") public static void housingAndLegacyRoundtrip(GameTestHelper helper){var c=city();UUID id=building(c,0),owner=UUID.randomUUID();var h=CityHousing.house(c,id);h.owner=owner;h.configured=true;h.workerLimit=2;h.product="minecraft:glass";h.baseline.put(0L,CityMaintenance.encode(Blocks.OAK_PLANKS.defaultBlockState()));CityHousing.seedCatalog(c.housing);c.housing.market.get("minecraft:glass").stock=9;var encoded=CityRegistry.export(c);var copy=city();CityRegistry.read(copy,encoded);helper.assertTrue(copy.housing.houses.get(id).owner.equals(owner)&&copy.housing.market.get("minecraft:glass").stock==9,"Registry export retains ownership, health, production and goods");encoded.remove("housing");var legacy=city();CityRegistry.read(legacy,encoded);helper.assertTrue(legacy.housing.houses.isEmpty(),"Old registry imports without changing its old jobs");helper.assertTrue(CityHousing.view(h).baseline.isEmpty(),"UI snapshot excludes potentially huge block baseline");var data=new CityData();data.cities.put(c.id,c);var archive=CityBlueprints.export(c);c.housing.houses.clear();CityBlueprints.apply(data,c,helper.getLevel(),archive,c.revision);helper.assertTrue(c.housing.houses.get(id).owner.equals(owner),"Full city import commits housing properties too");helper.succeed();}
 @GameTest(template="empty") public static void privateAndPublicMaterialPayments(GameTestHelper helper){var c=city();var id=building(c,0);var h=CityHousing.house(c,id);h.owner=UUID.randomUUID();var e=new CityEconomy();e.state.accounts.put(CityEconomy.treasury(c.id),100L);e.state.accounts.put(CityEconomy.person(h.owner),50L);var m=new CityHousing.Material();m.stock=100;m.priceCents=40;c.housing.market.put("minecraft:glass",m);h.personal=false;CityHousing.purchase(c,h,"minecraft:glass",10,e);helper.assertTrue(e.balance(CityEconomy.treasury(c.id))==96&&e.balance(CityEconomy.person(h.owner))==50,"Public house pays treasury only");h.personal=true;CityHousing.purchase(c,h,"minecraft:glass",10,e);helper.assertTrue(e.balance(CityEconomy.person(h.owner))==46&&e.balance(CityEconomy.treasury(c.id))==96&&m.stock==80&&h.materials.get("minecraft:glass")==20,"Private owner pays and real market goods move");helper.assertTrue(e.state.accounts.values().stream().mapToLong(Long::longValue).sum()==150,"No money minted or lost");helper.succeed();}
 @GameTest(template="empty") public static void tinyPaymentsAndFailedPurchaseAreAtomic(GameTestHelper helper){var c=city();var h=CityHousing.house(c,building(c,0));h.personal=false;var e=new CityEconomy();e.state.accounts.put(CityEconomy.treasury(c.id),1L);var m=new CityHousing.Material();m.stock=200;m.priceCents=1;c.housing.market.put("minecraft:dirt",m);for(int i=0;i<100;i++)CityHousing.purchase(c,h,"minecraft:dirt",1,e);helper.assertTrue(e.balance(CityEconomy.treasury(c.id))==0&&e.balance("market:"+c.id)==1&&m.stock==100,"100 lots of .01 settle exactly one silver");boolean failed=false;try{CityHousing.purchase(c,h,"minecraft:dirt",1,e);}catch(IllegalArgumentException ex){failed=true;}helper.assertTrue(failed&&m.stock==100&&h.materials.get("minecraft:dirt")==100,"Insufficient funds never remove goods");helper.succeed();}
 @GameTest(template="empty") public static void occupancyAndWorkCapacity(GameTestHelper helper){var c=city();UUID a=building(c,0),b=building(c,5),npc=UUID.randomUUID();c.residents.add(npc);var e=new CityEconomy();CityHousing.assign(c,a,npc,1,e);boolean blocked=false;try{CityHousing.assign(c,b,npc,1,e);}catch(IllegalArgumentException ex){blocked=true;}helper.assertTrue(blocked,"A resident cannot occupy two houses");var h=CityHousing.house(c,a);h.configured=true;h.workerLimit=0;blocked=false;try{CityHousing.capacity(c,a,npc,e);}catch(IllegalArgumentException ex){blocked=true;}helper.assertTrue(blocked,"Building worker limit has a real production consumer");CityHousing.assign(c,a,npc,1,e);helper.assertTrue(h.residents.isEmpty(),"Explicit unassignment works");helper.succeed();}
 @GameTest(template="empty") public static void boundedTestSupplyAndProductionClock(GameTestHelper helper){var state=new CityHousing.State();CityHousing.seedCatalog(state);CityHousing.advanceSupply(state,1200);helper.assertTrue(state.supplied==0,"Test supply is opt-in");state.testSupply=true;CityHousing.advanceSupply(state,1200);helper.assertTrue(state.market.get("minecraft:glass").stock==40&&state.supplied>0,"Synthetic goods visibly enter market");var h=new CityHousing.House();h.periodSeconds=2;h.quantity=3;UUID worker=UUID.randomUUID();state.market.get(h.product).stock=0;CityHousing.work(h,worker,state,20);helper.assertTrue(h.produced==0,"No output before earned work interval");CityHousing.work(h,worker,state,20);helper.assertTrue(h.produced==3&&state.market.get(h.product).stock==3,"Per-worker interval and quantity drive actual stock");state.market.get(h.product).stock=4096;CityHousing.work(h,worker,state,40);helper.assertTrue(h.produced==3&&h.progress.get(worker)==400000,"Full market retains earned pending batch");state.market.get(h.product).stock=4093;CityHousing.work(h,worker,state,20);helper.assertTrue(h.produced==6&&state.market.get(h.product).stock==4096,"Pending batch resumes without duplicating goods");helper.succeed();}
 @GameTest(template="empty") public static void healthAndSettingsPersistInCityData(GameTestHelper helper){var data=new CityData();var c=city();UUID id=building(c,0);var h=CityHousing.house(c,id);h.owner=UUID.randomUUID();h.baseline.put(0L,CityMaintenance.encode(Blocks.GLASS.defaultBlockState()));h.damaged.add(0L);data.cities.put(c.id,c);var loaded=CityData.load(data.save(new CompoundTag(),helper.getLevel().registryAccess()),helper.getLevel().registryAccess());helper.assertTrue(loaded.require(c.id).housing.houses.get(id).damaged.contains(0L),"Restart preserves building health and ownership");var old=data.save(new CompoundTag(),helper.getLevel().registryAccess());old.putInt("Schema",2);helper.assertTrue(CityData.load(old,helper.getLevel().registryAccess()).cities.size()==1,"Existing city schema2 remains readable");helper.succeed();}
}
